-- CAB-0004: scoped editorial import. Apply after the portrait assets are deployed.

begin;

do $$ begin
 if (select count(*) from public.entities where slug in ('pbb','umno') and type='party') <> 2 then raise exception 'CAB-0004: missing party parent'; end if;
 if exists(select 1 from public.entities where slug in ('mohamad-hasan','alexander-nanta-linggi') and (type <> 'politician' or owner_id is not null)) then raise exception 'CAB-0004: profile type or ownership conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('rembau','kapit') and slug not in ('mohamad-hasan','alexander-nanta-linggi')) then raise exception 'CAB-0004: constituency identity collision requires review'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'CAB-0004:%' and (m.source_type <> 'editorial' or e.slug not in ('mohamad-hasan','alexander-nanta-linggi') or m.import_key not like 'CAB-0004:' || e.slug || ':%')) then raise exception 'CAB-0004: milestone identity conflict'; end if;
end $$;

insert into public.entities (type, parent_id, slug, name, bloc, position, constituency, state, description, website, photo_path, photo_source_url, photo_credit, profile_checked_at, profile_sources)
select 'politician', parent.id, 'mohamad-hasan', 'Mohamad Hasan', 'government', 'Minister of Foreign Affairs; Deputy President of UMNO', 'Rembau', 'Negeri Sembilan', 'Mohamad Hasan, also known as Tok Mat, is Minister of Foreign Affairs and represents Rembau in Negeri Sembilan. He is Deputy President of UMNO, a component of Barisan Nasional.', 'https://www.kln.gov.my/', '/portraits/mohamad-hasan.webp', 'https://www.parlimen.gov.my/images/webuser/ahli/2022/P131.png', 'Parliament of Malaysia', '2026-11-08', '[{"label": "Prime Minister’s Office · Cabinet", "url": "https://www.pmo.gov.my/en/cabinet/"}, {"label": "Parliament · Rembau", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4170"}, {"label": "UMNO · deputy president (Nov 2026)", "url": "https://umno.org.my/jangan-salah-tafsir-kerjasama-damaikan-politik-melayu-mohamad-hasan/"}]'::jsonb from public.entities parent where parent.slug='umno'
on conflict (slug) do update set parent_id=excluded.parent_id, name=excluded.name, bloc=excluded.bloc, position=excluded.position, constituency=excluded.constituency, state=excluded.state, description=excluded.description, website=excluded.website, photo_path=excluded.photo_path, photo_source_url=excluded.photo_source_url, photo_credit=excluded.photo_credit, profile_checked_at=excluded.profile_checked_at, profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null;

insert into public.entities (type, parent_id, slug, name, bloc, position, constituency, state, description, website, photo_path, photo_source_url, photo_credit, profile_checked_at, profile_sources)
select 'politician', parent.id, 'alexander-nanta-linggi', 'Alexander Nanta Linggi', 'government', 'Minister of Works', 'Kapit', 'Sarawak', 'Alexander Nanta Linggi is Minister of Works and Member of Parliament for Kapit in Sarawak. He is a member of PBB, a component of Gabungan Parti Sarawak (GPS).', 'https://www.kkr.gov.my/', '/portraits/alexander-nanta-linggi.webp', 'https://www.parlimen.gov.my/images/webuser/ahli/2022/P215.jpg', 'Parliament of Malaysia', '2026-11-08', '[{"label": "Prime Minister’s Office · Cabinet", "url": "https://www.pmo.gov.my/en/cabinet/"}, {"label": "Parliament · Kapit", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4254"}, {"label": "PBB council meeting · 4 Nov 2026", "url": "https://lifenewsagency.com/fadillah-pbb-supreme-council-sarawak-election-preparations/"}]'::jsonb from public.entities parent where parent.slug='pbb'
on conflict (slug) do update set parent_id=excluded.parent_id, name=excluded.name, bloc=excluded.bloc, position=excluded.position, constituency=excluded.constituency, state=excluded.state, description=excluded.description, website=excluded.website, photo_path=excluded.photo_path, photo_source_url=excluded.photo_source_url, photo_credit=excluded.photo_credit, profile_checked_at=excluded.profile_checked_at, profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null;

do $$ begin if (select count(*) from public.entities where slug in ('mohamad-hasan','alexander-nanta-linggi') and type='politician' and owner_id is null) <> 2 then raise exception 'CAB-0004: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id, import_key, title, category, status, progress, target_date, promise_date, promise_url, evidence_date, evidence_url, description, progress_note, progress_checked_at, source_type, is_sample)
select e.id, 'CAB-0004:mohamad-hasan:asean-2045-launch', 'Launch ASEAN Community Vision 2045 at the May 2025 summit', 'Governance', 'achieved', null, '2025-05-31', '2025-02-06', 'https://bernama.com/en/general/news.php?id=2389936', '2025-05-26', 'https://asean.org/kuala-lumpur-declaration-on-asean-2045-our-shared-future/', 'Mohamad Hasan announced that ASEAN Community Vision 2045 and its strategic plans would be launched at the 46th ASEAN Summit in Kuala Lumpur in May 2025.', 'ASEAN’s official Kuala Lumpur Declaration dated 26 May 2025 establishes adoption of the vision and accompanying plans. Achieved is limited to this shared ASEAN launch/adoption milestone, not delivery of the vision’s long-term goals or sole personal credit. No numerical completion score is assigned.', '2026-11-08', 'editorial', false from public.entities e where e.slug='mohamad-hasan'
on conflict (import_key) do update set title=excluded.title, category=excluded.category, status=excluded.status, progress=excluded.progress, target_date=excluded.target_date, promise_date=excluded.promise_date, promise_url=excluded.promise_url, evidence_date=excluded.evidence_date, evidence_url=excluded.evidence_url, description=excluded.description, progress_note=excluded.progress_note, progress_checked_at=excluded.progress_checked_at, source_type=excluded.source_type, is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial';

insert into public.milestones (entity_id, import_key, title, category, status, progress, target_date, promise_date, promise_url, evidence_date, evidence_url, description, progress_note, progress_checked_at, source_type, is_sample)
select e.id, 'CAB-0004:alexander-nanta-linggi:kbkk-2027', 'Complete the Kota Bharu–Kuala Krai highway by 2027', 'Infrastructure', 'in_progress', 79, '2027-12-31', '2026-10-27', 'https://prn.bernama.com/sabah/news.php?id=2626275', '2026-10-27', 'https://prn.bernama.com/sabah/news.php?id=2626275', 'Nanta reported a 2027 completion forecast for the remaining packages of the 70.4-kilometre Kota Bharu–Kuala Krai highway.', 'Reported overall physical progress was 78.80% on 27 October 2026; the bar rounds this to 79%. Pasir Hor–Kadok was complete while five packages remained under construction. This is reported construction progress, not an independent audit or a percentage of time or cost saved. The date shown is the current delivery forecast, not an assessment of earlier schedules.', '2026-11-08', 'editorial', false from public.entities e where e.slug='alexander-nanta-linggi'
on conflict (import_key) do update set title=excluded.title, category=excluded.category, status=excluded.status, progress=excluded.progress, target_date=excluded.target_date, promise_date=excluded.promise_date, promise_url=excluded.promise_url, evidence_date=excluded.evidence_date, evidence_url=excluded.evidence_url, description=excluded.description, progress_note=excluded.progress_note, progress_checked_at=excluded.progress_checked_at, source_type=excluded.source_type, is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial';

insert into public.milestones (entity_id, import_key, title, category, status, progress, target_date, promise_date, promise_url, evidence_date, evidence_url, description, progress_note, progress_checked_at, source_type, is_sample)
select e.id, 'CAB-0004:alexander-nanta-linggi:pan-borneo-sabah-2030', 'Complete the remaining Pan Borneo Sabah Phase 1 packages by 2030', 'Infrastructure', 'in_progress', null, '2030-12-31', '2026-10-27', 'https://prn.bernama.com/sabah/news.php?id=2626275', '2026-10-27', 'https://prn.bernama.com/sabah/news.php?id=2626275', 'Nanta stated that the remaining 31 of 35 Pan Borneo Sabah Phase 1 work packages would be completed progressively by 2030.', 'The October 2026 statement reports four completed packages, Phase 1A physical progress of 89.54% and Phase 1B progress of 25.53%. These phase-specific percentages are not combined or presented as overall completion because the required weighting was not supplied. Overall completion therefore remains blank.', '2026-11-08', 'editorial', false from public.entities e where e.slug='alexander-nanta-linggi'
on conflict (import_key) do update set title=excluded.title, category=excluded.category, status=excluded.status, progress=excluded.progress, target_date=excluded.target_date, promise_date=excluded.promise_date, promise_url=excluded.promise_url, evidence_date=excluded.evidence_date, evidence_url=excluded.evidence_url, description=excluded.description, progress_note=excluded.progress_note, progress_checked_at=excluded.progress_checked_at, source_type=excluded.source_type, is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial';

commit;
